"""Load rate-limit config — fixed: fail closed on bad config."""

from __future__ import annotations

from pathlib import Path

DEFAULTS = {"max_requests": 5, "window_seconds": 60.0}

FAIL_CLOSED = {"max_requests": 0, "window_seconds": 60.0}


def load_limits(path: str | None) -> dict:
    if path is None:
        return dict(DEFAULTS)
    p = Path(path)
    if not p.is_file():
        # Fail closed — deny all traffic
        return dict(FAIL_CLOSED)
    max_requests = DEFAULTS["max_requests"]
    window_seconds = DEFAULTS["window_seconds"]
    try:
        for raw in p.read_text(encoding="utf-8").splitlines():
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            if "=" not in line:
                continue
            k, v = line.split("=", 1)
            k, v = k.strip(), v.strip()
            if k == "max_requests":
                max_requests = int(v)
            elif k == "window_seconds":
                window_seconds = float(v)
    except Exception:
        # Fail closed on parse errors
        return dict(FAIL_CLOSED)
    return {"max_requests": max_requests, "window_seconds": window_seconds}

"""Hit store — fixed: per-key storage, proper sliding window."""

from __future__ import annotations

from collections import defaultdict


class HitStore:
    def __init__(self) -> None:
        # Per-key hit lists for isolation
        self._hits: dict[str, list[float]] = defaultdict(list)

    def record(self, key: str, ts: float) -> None:
        self._hits[key].append(ts)

    def hits_in_window(self, key: str, now: float, window_seconds: float) -> int:
        # Sliding window: (now - window_seconds, now] — exclusive left, inclusive right
        cutoff = now - window_seconds
        return sum(1 for t in self._hits[key] if t > cutoff and t <= now)
